export function Legend({
  seriesCount = "{{seriesCount}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  showValues = {{showValues}},
}) {
  const series = [{"name":"Series A","value":"42%","pattern":"solid"},{"name":"Series B","value":"28%","pattern":"stripes"},{"name":"Series C","value":"18%","pattern":"dots"},{"name":"Series D","value":"12%","pattern":"cross"}];
  const fixedColors = ["", "#F5C2E0", "#BFD9F2", "#E8A020"];
  const patternStyle = (i) => {
    if (i === 0) return { background: accent };
    if (i === 1) return { background: fixedColors[1], backgroundImage: "repeating-linear-gradient(45deg,#241430 0 2px,transparent 2px 5px)" };
    if (i === 2) return { background: fixedColors[2], backgroundImage: "radial-gradient(#241430 1px,transparent 1px)", backgroundSize: "5px 5px" };
    return {
      background: fixedColors[3],
      backgroundImage: "repeating-linear-gradient(0deg,#241430 0 1px,transparent 1px 4px),repeating-linear-gradient(90deg,#241430 0 1px,transparent 1px 4px)",
    };
  };
  const count = Number(seriesCount);
  const visible = series.slice(0, count);
  return (
    <ul style={{
      listStyle: "none", margin: 0, padding: 0, font: "14px/1.4 system-ui, sans-serif", color: "#241430",
      display: "flex", flexDirection: layout === "vertical" ? "column" : "row",
      flexWrap: layout === "horizontal" ? "wrap" : "nowrap", gap: layout === "vertical" ? 8 : 14,
    }}>
      {visible.map((s, i) => (
        <li key={s.name} style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span aria-hidden="true" style={{ width: 14, height: 14, borderRadius: 3, border: "1px solid #24143033", ...patternStyle(i) }} />
          <span>{s.name}{showValues && ` \u2014 ${s.value}`}</span>
        </li>
      ))}
    </ul>
  );
}
